import fixtures from './golden/prototype-payoff.json';
import { amortise } from '../amortise';
import { futureValue } from '../futureValue';
import { simulateMinimum } from '../simulateMinimum';
import { percent, type CardMinimumTerms } from '../types';
import { minorUnits } from '../../money/types';

// D-22 parity against prototype-payoff.json (generated by running the prototype's own code).
const m = minorUnits;
const PROTO: CardMinimumTerms = { minimumPercent: percent('1'), interestAdded: true, floor: m(2_500) };

describe.each(fixtures.dpmt)('dpmt parity: $name', (c) => {
  it('payment within 1 minor unit', () => {
    const [p, apr, n] = c.args as [number, number, number];
    const r = amortise(m(Math.round(p * 100)), percent(String(apr)), n);
    expect(Math.abs(r.payment - c.paymentMinor)).toBeLessThanOrEqual(1);
  });
});

describe.each(fixtures.dfv)('dfv parity: $name', (c) => {
  it('value within 1 minor unit', () => {
    const [mo, apr, n, seed] = c.args as [number, number, number, number];
    const v = futureValue(m(Math.round(mo * 100)), percent(String(apr)), n, m(Math.round(seed * 100)));
    expect(Math.abs(v - c.valueMinor)).toBeLessThanOrEqual(1);
  });
});

describe.each(fixtures.dSimMin)('dSimMin parity: $name', (c) => {
  it('matches first payment, months and total interest within bounds', () => {
    const [bal, rate] = c.args as [number, number];
    const r = simulateMinimum(m(Math.round(bal * 100)), percent(String(rate)), PROTO);
    expect(c.never).toBe(false);
    expect(r.outcome).toBe('cleared');
    expect(Math.abs(r.firstPayment - c.firstMinor)).toBeLessThanOrEqual(1);
    // The prototype stops at a float balance <= 0.5; the engine at integer 0: at most one extra month.
    expect(Math.abs(r.months - c.months)).toBeLessThanOrEqual(1);
    // Aggregated interest differs by the documented per-month rounding bound (see the D-20 deviation test).
    expect(Math.abs(Number(r.totalInterest) - Number(c.interestMinor))).toBeLessThanOrEqual(
      Math.ceil(r.months / 2) + 1
    );
  });
});
